import type { DegradeReport } from '../generate/degrade';
import type { EvalRun } from '../run';
import type { EvalSummary } from '../types';
import type { CalibrationPoint } from './calibrate';

/**
 * docs/evaluation.md, from a run. Regenerated by `pnpm eval:doc`, never
 * edited by hand, so every number in it is one the harness produced — and
 * the caveats travel with the numbers rather than living in a README
 * paragraph someone can forget to update.
 */
export interface ReportInput {
  readonly clean: EvalRun;
  /** Degraded profile at the tier-1 default threshold — what the gate baselines. */
  readonly degraded: EvalRun;
  /** The same packs at the calibrated knee, so the gain is measured rather than asserted. */
  readonly degradedAtKnee: EvalRun | null;
  readonly curve: readonly CalibrationPoint[];
  readonly knee: CalibrationPoint | null;
  readonly heldOutLines: number;
  readonly heldOutDegraded: number;
  readonly generatedAt: string;
  readonly seedBase: number;
}

const pct = (x: number, dp = 1): string => `${(x * 100).toFixed(dp)}%`;
const n = (x: number): string => x.toLocaleString('en-IN');

export function renderEvaluationDoc(r: ReportInput): string {
  const c = r.clean.summary;
  const d = r.degraded.summary;
  const k = r.degradedAtKnee?.summary ?? null;
  const kneeLabel = r.knee ? `degraded @ ${r.knee.threshold.toFixed(2)}` : 'degraded @ knee';
  const col = (f: (s: EvalSummary) => string): string =>
    `| ${f(c)} | ${f(d)} |${k ? ` ${f(k)} |` : ''}`;
  const out: string[] = [];

  out.push(
    '# Evaluation',
    '',
    `Generated by \`pnpm eval:doc\` at ${r.generatedAt} over seeds ${r.seedBase}–${r.seedBase + c.packs - 1}.`,
    'Do not edit by hand — every figure below is produced by the harness in `packages/eval`.',
    '',
    '## What is being measured',
    '',
    'Each pack is a seeded, generated claim: a sampled policy, an admission of one of four',
    'archetypes, an itemised bill composed to match it, and a deduction sheet settled **by the',
    "engine's own arithmetic** so that the lawful baseline is exact. Zero to three fault",
    'operators then inject unlawful rupees with a known clause and a known amount. A fault',
    'counts as detected when the engine emits an `INCORRECTLY_APPLIED` finding on the same line,',
    'citing the same clause, within ₹1 of the injected amount. A dispute no fault explains is a',
    'false positive. Zero-fault packs are the control set; each is credited only with the lawful',
    'deductions it actually contains.',
    '',
    'Two profiles run over the same packs:',
    '',
    '- **clean** — rows exactly as generated, categories by construction. This measures the',
    '  waterfall alone: does it attribute known unlawful rupees to the right clause, and leave',
    '  lawful ones alone.',
    '- **degraded** — descriptions and digits perturbed the way OCR perturbs them, sheet rows',
    '  occasionally missing, and categories assigned by the real tier-1 normaliser at its §14',
    '  default threshold. This measures the system as far as it exists without AWS: the',
    '  normalisation gate, the sheet matcher and the waterfall together.',
    `- **${kneeLabel}** — the same degraded packs with the normaliser at the threshold the`,
    '  calibration below recommends. Reported so the effect of adopting it is a number.',
    '',
    '**Neither is a claim about real-world accuracy.** The corpus is generated, its phrasing is',
    'ours, its noise model is a working assumption, and the lawful baseline is settled by the',
    'same rules the engine enforces. See `fixtures/corpus/PROVENANCE.md`.',
    '',
  );

  const head = k ? `| | clean | degraded | ${kneeLabel} |` : '| | clean | degraded |';
  const rule = k ? '|---|---:|---:|---:|' : '|---|---:|---:|';
  out.push('## Headline', '', head, rule);
  out.push(`| packs ${col((s) => String(s.packs))}`);
  out.push(`| injected faults ${col((s) => String(s.faults))}`);
  out.push(`| detected ${col((s) => `${s.detected} (${pct(rate(s))})`)}`);
  out.push(`| control packs disputing a lawful cut ${col((s) => pct(s.controlFalsePositiveRate))}`);
  out.push(`| mean attribution error ${col((s) => `${s.meanAttributionErrorPaise.toFixed(0)} paise`)}`);
  out.push(`| bill lines gated by step 2 ${col((s) => pct(s.gatedLineRate))}`);
  out.push(`| bill lines with no matching sheet row ${col((s) => pct(s.unmatchedLineRate))}`);
  out.push('');

  out.push('## Per clause', '');
  out.push(perClauseTable('clean', c), '', perClauseTable('degraded', d), '');
  if (k) out.push(perClauseTable(kneeLabel, k), '');

  out.push(
    '## Where the degraded profile loses faults',
    '',
    'A miss is attributed to the first of three causes that applies: the line was **gated**',
    '(the normaliser could not place it, so step 2 excluded it from adjudication), the line was',
    '**unmatched** (its sheet row no longer paired with the bill row, so the engine had no',
    'insurer cut to classify), or **engine** — the line reached the waterfall intact and the',
    'engine still did not cite it. Only the last is an engine defect; the first two are the',
    'extraction layer doing what it is supposed to do with input it cannot trust.',
    '',
    k ? `| cause | clean | degraded | ${kneeLabel} |` : '| cause | clean | degraded |',
    rule,
    `| gated ${col((s) => String(s.missesByReason.GATED))}`,
    `| unmatched ${col((s) => String(s.missesByReason.UNMATCHED))}`,
    `| engine ${col((s) => String(s.missesByReason.ENGINE))}`,
    '',
  );

  const tiers = sumTiers(r.degraded.degradation);
  const totalTiers = Object.values(tiers).reduce((s, x) => s + x, 0);
  out.push(
    '### Normalisation tiers under degradation',
    '',
    'Tiers 2 and 3 (Titan embeddings, the Claude tie-break) are Bedrock calls and do not run',
    'locally, so everything tier 1 cannot place is `UNRESOLVED` here. In production those lines',
    'would be attempted by the next tier before being gated.',
    '',
    '| tier | lines | share |',
    '|---|---:|---:|',
    ...Object.entries(tiers).map(([t, k]) => `| ${t} | ${n(k)} | ${pct(totalTiers === 0 ? 0 : k / totalTiers)} |`),
    '',
  );

  out.push(
    '## By archetype',
    '',
    `| archetype | packs | faults | detected (clean) | detected (degraded) |${k ? ` detected (${kneeLabel}) |` : ''}`,
    `|---|---:|---:|---:|---:|${k ? '---:|' : ''}`,
    ...Object.entries(c.byArchetype).map(([name, a]) => {
      const key = name as keyof typeof d.byArchetype;
      return `| ${name} | ${a.packs} | ${a.faults} | ${a.detected} | ${d.byArchetype[key].detected} |${k ? ` ${k.byArchetype[key].detected} |` : ''}`;
    }),
    '',
  );

  out.push(
    '## Control coverage',
    '',
    'How many zero-fault packs demonstrated each lawful deduction. A control is only evidence',
    'when the deduction is on the sheet, and the regression gate fails if any of these drops',
    'to zero.',
    '',
    '| control | packs (clean) |',
    '|---|---:|',
    ...Object.entries(c.controlCoverage).map(([k, v]) => `| ${k} | ${v} |`),
    '',
  );

  out.push(
    '## Calibration — the tier-1 threshold',
    '',
    `Swept over ${n(r.heldOutLines)} labelled bill lines from a held-out seed range (${n(r.heldOutDegraded)} of`,
    'them OCR-degraded), disjoint from the packs above. Accuracy is among the lines the fuzzy',
    'tier accepted; escalation is the share it declined to place. The knee is the lowest',
    'threshold whose accuracy among accepted lines stays at or above 99.9%: a wrong category',
    'is a wrong clause in a letter, so the accuracy floor is fixed and escalation is what gives.',
    '',
    '§14 calibrates the embedding-margin τ of tier 2 the same way. Tier 2 needs Titan and is',
    'not in this slice; this curve is for the one threshold the local cascade has.',
    '',
    '| threshold | accepted | correct | escalated | accuracy among accepted | escalation rate |',
    '|---:|---:|---:|---:|---:|---:|',
    ...r.curve.map(
      (p) =>
        `| ${p.threshold.toFixed(2)}${r.knee && p.threshold === r.knee.threshold ? ' **←**' : ''} | ${p.accepted} | ${p.correct} | ${p.escalated} | ${pct(p.accuracyAmongAccepted, 2)} | ${pct(p.escalationRate)} |`,
    ),
    '',
    r.knee
      ? `Knee: **${r.knee.threshold.toFixed(2)}** — accuracy ${pct(r.knee.accuracyAmongAccepted, 2)} among accepted, escalating ${pct(r.knee.escalationRate)}. The \`degraded\` column and the regression gate run at the §14 default of 0.92; the \`${kneeLabel}\` column shows the same packs at the recommended operating point. The default is not changed by this document — adopting the knee is a rulepack decision, made with the curve in front of you.`
      : 'No threshold in the sweep met the accuracy floor.',
    '',
  );

  out.push(
    '## What these numbers are not',
    '',
    '- Not evidence about real Indian hospital billing. Phrasing, prevalences and amounts are',
    '  sampled from distributions we chose.',
    '- Not evidence that our encoding of the IRDAI circular matches how a practitioner reads it.',
    '  The lawful baseline is settled by the same rules the engine enforces.',
    '- Not a measurement of Textract. The degraded profile reproduces the *consequences* of OCR',
    '  error at the row level; layout-dependent failures need the render path.',
    '',
  );

  return out.join('\n');
}

const rate = (s: EvalSummary): number => (s.faults === 0 ? 1 : s.detected / s.faults);

function perClauseTable(label: string, s: EvalSummary): string {
  const rows = [
    `**${label}**`,
    '',
    '| clause | tp | fp | fn | precision | recall |',
    '|---|---:|---:|---:|---:|---:|',
  ];
  for (const c of s.perClause) {
    rows.push(`| ${c.clauseId} | ${c.tp} | ${c.fp} | ${c.fn} | ${c.precision.toFixed(2)} | ${c.recall.toFixed(2)} |`);
  }
  return rows.join('\n');
}

function sumTiers(reports: readonly DegradeReport[]): Record<string, number> {
  const acc: Record<string, number> = { LEXICON: 0, LEXICON_FUZZY: 0, EMBEDDING: 0, LLM: 0, UNRESOLVED: 0 };
  for (const r of reports) for (const [t, k] of Object.entries(r.tiers)) acc[t] = (acc[t] ?? 0) + k;
  return acc;
}
